  function spawnEnemy() {
    var size = 10 + Math.random() * 14;
    var type = Math.random();
    var hp;
    var speed;
    var color;
    if (type < 0.2) {
      hp = 3; speed = 60 + runningTime * 4; color = '#ff6a6a';
    } else if (type < 0.55) {
      hp = 2; speed = 90 + runningTime * 5; color = '#ffb84d';
    } else {
      hp = 1; speed = 130 + runningTime * 6; color = '#9bf';
    }
    enemies.push({
      x: Math.random() * (W - 40) + 20,
      y: -30,
      w: size * 2,
      h: size * 2,
      speed: Math.min(speed, 240),
      hp: hp,
      color: color,
      phase: Math.random() * Math.PI * 2,
      drift: Math.random() * 60 + 20
    });
