    if (keys['ArrowRight'] || keys['KeyD']) dirX += 1;
    if (keys['ArrowUp'] || keys['KeyW']) dirY -= 1;
    if (keys['ArrowDown'] || keys['KeyS']) dirY += 1;

    if (dirX !== 0 && dirY !== 0) {
      dirX *= 0.7071;
      dirY *= 0.7071;
    }

    if (player.alive) {
      player.x += dirX * player.speed * dt;
      player.y += dirY * player.speed * dt;
      player.x = Math.max(20, Math.min(W - 20, player.x));
      player.y = Math.max(20, Math.min(H - 20, player.y));

      player.invuln = Math.max(0, player.invuln - dt);
      player.fireCooldown -= dt;
      if ((keys['Space'] || keys['ArrowUp'] || keys['KeyW']) && player.fireCooldown <= 0) {
        fireBullet();
        player.fireCooldown = player.fireRate;
      }
    }

    for (i = bullets.length - 1; i >= 0; i--) {
      var b = bullets[i];
      b.y -= b.speed * dt;
      if (b.y < -20) bullets.splice(i, 1);
